// Writes docs/site/reference/shortcuts.md from the app's shortcut registry (packages/web/src/shortcuts.ts, leader.ts).
// Runs before `docs:dev` and `docs:build`, so the page always matches the code. Do not edit the generated page by hand.
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { SHORTCUTS, keyLabels, type Shortcut, type ShortcutGroup } from "../../../packages/web/src/shortcuts.ts";
import { PREFIX_KEYS } from "../../../packages/web/src/leader.ts";
// The catalog file itself, not i18n.ts: that one needs Vite's import.meta.glob, which plain tsx lacks.
import viSettings from "../../../packages/web/src/i18n/vi/settings.ts";

type Lang = "en" | "vi";
const vi: Record<string, unknown> = viSettings;
/** The app's own title of a shortcut in `lang` (the Vietnamese catalog, English `title` as the fallback). */
const title = (lang: Lang, key: string, en: string) => (lang === "vi" && typeof vi[key] === "string" ? vi[key] : en);

/** "mod+shift+p" -> "<kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>P</kbd>" (or the macOS symbols). */
const kbd = (spec: string, mac: boolean) =>
  keyLabels(spec, mac)
    .map((k) => `<kbd>${k === "`" ? "\\`" : k === "\\" ? "\\\\" : k === "|" ? "\\|" : k}</kbd>`)
    .join(mac ? " " : "+");

const row = (lang: Lang, s: Shortcut & { key: string }) => `| ${title(lang, `shortcut.${s.id}`, s.title)} | ${kbd(s.key, false)} | ${kbd(s.mac ?? s.key, true)} |`;

// Tabs 1..8 collapse into one row. Commands without a default key (a user may bind them in the app) are not shortcuts to list.
const rows = (lang: Lang, group: ShortcutGroup) => {
  const list = SHORTCUTS.filter((s): s is Shortcut & { key: string } => s.group === group && !!s.key);
  const lines: string[] = [];
  for (const s of list) {
    if (/^tab\.goto[2-8]$/.test(s.id)) continue;
    if (s.id === "tab.goto1") {
      lines.push(`| ${lang === "vi" ? "Đến tab 1 đến 8" : "Go to tab 1 to 8"} | ${kbd("alt+1", false)} … ${kbd("alt+8", false)} | ${kbd("ctrl+1", true)} … ${kbd("ctrl+8", true)} |`);
      continue;
    }
    lines.push(row(lang, s));
  }
  return lines.join("\n");
};

const table = (lang: Lang, group: ShortcutGroup) =>
  `| ${lang === "vi" ? "Thao tác" : "Action"} | Windows / Linux | macOS |\n| --- | --- | --- |\n${rows(lang, group)}`;

const prefix = (lang: Lang) =>
  PREFIX_KEYS.map((p) => {
    const does = p.key === "1-9" ? (lang === "vi" ? "Tab 1 đến 9 (9 = tab cuối)" : "Tab 1 to 9 (9 = last tab)") : title(lang, `shortcut.prefix.${p.id}`, p.title);
    return `| <kbd>${p.key === "1-9" ? "1</kbd> … <kbd>9" : p.key}</kbd> | ${does} |`;
  }).join("\n");

const PAGES: Record<Lang, string> = {
  en: `---
title: Keyboard shortcuts
editLink: false
---

<!-- Generated by docs/site/scripts/gen-shortcuts.ts from packages/web/src/shortcuts.ts and leader.ts. Do not edit by hand. -->

# Keyboard shortcuts

Shortcuts work anywhere in the app, including the prompt box, except as noted under Good to know.

![The Keyboard shortcuts dialog](/screenshots/shortcuts.png)

## How to use

1. Press <kbd>Ctrl</kbd>+<kbd>/</kbd> (<kbd>⌘</kbd> <kbd>/</kbd> on a Mac) to open the **Keyboard shortcuts** dialog.
2. Type in **Filter by name or key** to find one.
3. Click **Edit** next to it and press the new keys. <kbd>Esc</kbd> cancels, <kbd>Backspace</kbd> removes the shortcut.
4. The reset button next to a changed shortcut brings back the default. **Reset all** resets every one.
5. Your changes are kept in this browser only.

## General

${table("en", "General")}

## Tabs

${table("en", "Tabs")}

## Panels

${table("en", "Panels")}

## Session

${table("en", "Session")}

## Prefix key

Press <kbd>Alt</kbd>+<kbd>A</kbd> (like tmux), let go, then press one more key within 1.5 seconds:

| Then press | Does |
| --- | --- |
${prefix("en")}

## In the prompt box

These are fixed (not in the registry).

| Key | Does |
| --- | --- |
| <kbd>Enter</kbd> | Send (while Claude works: steer, see [The prompt box](../features/prompt-box)) |
| <kbd>Shift</kbd>+<kbd>Enter</kbd> | New line |
| <kbd>Shift</kbd>+<kbd>Tab</kbd> | Next permission mode |
| <kbd>Esc</kbd> | Stop the running turn |
| <kbd>!</kbd> at the start | Bash mode: the line runs as a shell command |
| <kbd>Ctrl</kbd>+<kbd>B</kbd> / <kbd>I</kbd> / <kbd>E</kbd> | Bold / italic / inline code (<kbd>⌘</kbd> on a Mac) |

## Good to know

- On Windows and Linux some keys use <kbd>Alt</kbd> because the browser keeps <kbd>Ctrl</kbd>+<kbd>T</kbd>, <kbd>Ctrl</kbd>+<kbd>W</kbd>, <kbd>Ctrl</kbd>+<kbd>Tab</kbd> and <kbd>Ctrl</kbd>+<kbd>1</kbd>…<kbd>9</kbd> for itself.
- The recorder refuses keys that would break typing: a key without <kbd>Ctrl</kbd>, <kbd>Cmd</kbd> or <kbd>Alt</kbd>, AltGr characters, macOS Option characters, and the prompt box's editing keys (copy, paste, undo, word jumps).
- <kbd>Ctrl</kbd>+<kbd>B</kbd> toggles the sidebar, except in the prompt box, where it makes text bold.
- In the terminal panel, plain <kbd>Ctrl</kbd>+letter keys go to the shell. Shortcuts with <kbd>Alt</kbd>, the tab keys, the palette, the shortcuts dialog and the terminal keys still reach the app.
`,
  vi: `---
title: Phím tắt
editLink: false
---

<!-- Generated by docs/site/scripts/gen-shortcuts.ts from packages/web/src/shortcuts.ts and leader.ts. Do not edit by hand. -->

# Phím tắt {#keyboard-shortcuts}

Phím tắt hoạt động ở mọi nơi trong ứng dụng, kể cả ô prompt, trừ các trường hợp ghi ở mục Cần biết.

![Hộp thoại Phím tắt](/screenshots/shortcuts.png)

## Cách dùng {#how-to-use}

1. Nhấn <kbd>Ctrl</kbd>+<kbd>/</kbd> (<kbd>⌘</kbd> <kbd>/</kbd> trên Mac) để mở hộp thoại **Phím tắt**.
2. Gõ vào ô **Lọc theo tên hoặc phím** để tìm.
3. Nhấn **Sửa** bên cạnh phím tắt rồi nhấn tổ hợp phím mới. <kbd>Esc</kbd> để hủy, <kbd>Backspace</kbd> để gỡ phím tắt.
4. Nút đặt lại bên cạnh phím tắt đã đổi sẽ khôi phục mặc định. **Đặt lại tất cả** khôi phục toàn bộ.
5. Thay đổi chỉ được lưu trong trình duyệt này.

## Chung {#general}

${table("vi", "General")}

## Tab {#tabs}

${table("vi", "Tabs")}

## Bảng {#panels}

${table("vi", "Panels")}

## Phiên {#session}

${table("vi", "Session")}

## Phím tiền tố {#prefix-key}

Nhấn <kbd>Alt</kbd>+<kbd>A</kbd> (giống tmux), thả ra, rồi nhấn thêm một phím trong vòng 1,5 giây:

| Nhấn tiếp | Tác dụng |
| --- | --- |
${prefix("vi")}

## Trong ô prompt {#in-the-prompt-box}

Các phím này cố định (không nằm trong danh sách có thể đổi).

| Phím | Tác dụng |
| --- | --- |
| <kbd>Enter</kbd> | Gửi (khi Claude đang làm việc: điều hướng, xem [Ô prompt](../features/prompt-box)) |
| <kbd>Shift</kbd>+<kbd>Enter</kbd> | Xuống dòng |
| <kbd>Shift</kbd>+<kbd>Tab</kbd> | Chế độ quyền tiếp theo |
| <kbd>Esc</kbd> | Dừng lượt đang chạy |
| <kbd>!</kbd> ở đầu dòng | Chế độ Bash: dòng được chạy như lệnh shell |
| <kbd>Ctrl</kbd>+<kbd>B</kbd> / <kbd>I</kbd> / <kbd>E</kbd> | In đậm / in nghiêng / mã nội dòng (<kbd>⌘</kbd> trên Mac) |

## Cần biết {#good-to-know}

- Trên Windows và Linux, một số phím dùng <kbd>Alt</kbd> vì trình duyệt giữ <kbd>Ctrl</kbd>+<kbd>T</kbd>, <kbd>Ctrl</kbd>+<kbd>W</kbd>, <kbd>Ctrl</kbd>+<kbd>Tab</kbd> và <kbd>Ctrl</kbd>+<kbd>1</kbd>…<kbd>9</kbd> cho chính nó.
- Trình ghi phím từ chối các phím làm hỏng việc gõ: phím không có <kbd>Ctrl</kbd>, <kbd>Cmd</kbd> hoặc <kbd>Alt</kbd>, ký tự AltGr, ký tự Option trên macOS, và các phím soạn thảo của ô prompt (sao chép, dán, hoàn tác, nhảy theo từ).
- <kbd>Ctrl</kbd>+<kbd>B</kbd> bật/tắt thanh bên, trừ trong ô prompt, nơi nó in đậm chữ.
- Trong bảng terminal, các phím <kbd>Ctrl</kbd>+chữ cái thông thường được gửi tới shell. Phím tắt có <kbd>Alt</kbd>, các phím tab, bảng lệnh, hộp thoại phím tắt và các phím terminal vẫn đến được ứng dụng.
`,
};

for (const [lang, page] of Object.entries(PAGES)) {
  const out = fileURLToPath(new URL(`../${lang === "en" ? "" : `${lang}/`}reference/shortcuts.md`, import.meta.url));
  writeFileSync(out, page);
  console.log(`wrote ${out}`);
}
